const TOK=$('Init Seats').first().json.run_token;const RT=' run_token='+TOK;
// D2: DEFENDER ROUND 2, RESPONSE. Body built by API family; model from model_config by seat.
const FAMS=['anthropic','openai','gemini','grok','mimo','openrouter','deepseek'];
const bodyFor=(fam,model,tok,sys,msgs)=>{
 if(fam==='anthropic')return {model,max_tokens:tok,system:[{type:'text',text:sys,cache_control:{type:'ephemeral',ttl:'1h'}}],messages:msgs};
 if(fam==='gemini')return {systemInstruction:{parts:[{text:sys}]},contents:msgs.map(m=>({role:m.role==='assistant'?'model':'user',parts:[{text:m.content}]})),generationConfig:{maxOutputTokens:tok}};
 const m=[{role:'system',content:sys},...msgs];
 if(fam==='openai')return {model,max_completion_tokens:tok,messages:m};
 // ORDER J (BB-6200): glm debates at reasoning effort medium, as qwen does; at max it returned no text (ODV1-26217 C1, ODV1-26238 C3).
 // BB-8403 S3: chatgpt via OpenRouter (openai/) at reasoning effort medium; at max it spent the whole 32,000 in reasoning and returned no text (ODV1-29876 C1). Token budget as its openai branch: max(mt*2,8000).
 // BB-8510 S2: gemini via OpenRouter (google/), effort medium; max_tokens and temperature as its former generationConfig (KB-0042, KB-0077).
 if(fam==='openrouter'&&/^google\//.test(model))return {model,max_tokens:tok,reasoning:{effort:'medium'},messages:m};
 if(fam==='openrouter'&&/^openai\//.test(model))return {model,max_tokens:Math.max(tok*2,8000),reasoning:{effort:'medium'},messages:m};
 if(fam==='openrouter')return {model,max_tokens:tok,reasoning:{effort:/^(?:qwen\/|z-ai\/glm-)/.test(model)?'medium':'max'},messages:m};
 return {model,max_tokens:tok,messages:m};};
const I=$('Init with Guards').first().json;const R=$('Resolve Seats').first().json;
const call=(seat,sys,msgs)=>{const idx=FAMS.indexOf(seat.fam);if(idx<0)throw new Error('ORACLE_DEBATE_V1: no call path for family '+seat.fam+RT);return {fam:seat.fam,fam_idx:idx,model:seat.model,body:bodyFor(seat.fam,seat.model,seat.tok,sys,msgs)};};
const DD=`\n\n=== DEFENSE DISCIPLINE (Eric-ruled 2026-07-18; protocol_debate_engine DD-1..DD-3) ===\n\nDD-1. SCOPE VS AMMUNITION. The debate's scope is the question and its citation CHAIN; the verse is ammunition, not the battlefield. A challenger's point about an isolated term or verse is answered by re-seating that term in its chain — context, grammar floor, cross-reference — never by adjudicating the term in isolation. A term stripped of its chain proves nothing and concedes nothing.\n\nDD-2. NO IN-ROUND CONCESSION. No concession, re-grade, or framework adjustment is ever made on the opponent's clock. The only in-battle response to a correction — however textually accurate — is: "Noted. Not conceding here. Goes to review." All self-examination happens in cold review: full record, our ground, opponent not in the room. A defense that concedes in-round to a context-stripped term is a defense-discipline slip and must be flagged in review even when the verdict still lands HELD.\n\nDD-3. CHAIN-SCOPED FRAMING — Isaiah 28:10 as rule of engagement. Debate topics are framed at the chain level: the framework's case is its interlocking citations — precept upon precept, line upon line, here a little, there a little — and the challenger must break the CHAIN, not one link. Isaiah 28:10 is declared in the topic framing as the rule of engagement; it is never cited inside L3 as a witness for a conclusion — that is citing the method as evidence, and DG-29 cuts both ways.`;const sys=I.dsys+DD;const msgs=[{role:'user',content:'DEBATE TOPIC: '+I.topic},{role:'assistant',content:$('D1 Extract').first().json.raw},{role:'user',content:'THE CHALLENGER ANSWERED:\n\n'+$('C1 Extract').first().json.raw+'\n\nRound 2. Tag every layer.'}];
return [{json:{run_token:TOK,round:'D2',call:call(R.defender,sys,msgs)}}];
